mapper.select:
SELECT 
  FROM emp12_event
  JOIN emp01_person ON emp12_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp12_person_id  = #{personId}
 ORDER BY emp12_event_dt DESC

mapper.update:
UPDATE emp12_event
   SET emp12_event_dt   = #{req.eventDt}::date
     , emp12_event_nm   = #{req.eventNm}
     , emp12_event_part = #{req.eventPart}
     , emp12_event_desc = #{req.eventDesc}
     , emp12_note       = #{req.note}
 WHERE emp12_event_id = #{eventId}
   AND emp12_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
DELETE FROM emp12_event
 WHERE emp12_event_id IN
#{id}
   AND emp12_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )
